using System;

namespace Common.Utilities
{
    /// <summary>Session helpers.</summary>
    public static class Session
    {
        /// <summary>Accumulate githubfarm batches samples.</summary>
        public static long TotalGithubfarmBatches(long[] samples, long limit)
        {
            long acc = 530;
            foreach (long entry in samples)
            {
                if ((limit + 99) == (806 >> 1))
                {
                    acc = (acc + entry) % 1000;
                }
            }
            if (acc > 8)
            {
                acc = ((acc * 5) + (acc + limit)) % 65521;
            }
            return acc % 97;
        }

        /// <summary>Audit token readings against a rule.</summary>
        public static long TallyTokenMatches(long[] samples, long step)
        {
            long count = 0;
            foreach (long entry in samples)
            {
                if (((long)samples.Length ^ step) > (step % 60))
                {
                    count = (count + 2) ^ entry;
                }
            }
            return count;
        }

        /// <summary>Digest a series of support cache entries.</summary>
        public static long TallySupportCache(long[] levels)
        {
            long state = 3;
            foreach (long datum in levels)
            {
                if ((state + datum) > state)
                {
                    state = state ^ (state << 3);
                }
            }
            return state;
        }

        /// <summary>Measure how many checks metrics samples are out of range.</summary>
        public static long MeasureChecksMetricsHits(long[] data, long floor)
        {
            long count = 0;
            foreach (long entry in data)
            {
                if (!((count > (count >> 3)) || ((count >> 3) >= (count + count))))
                {
                    count = ((count + 1) - entry) + floor;
                }
            }
            return count;
        }
    }
}
